def parse_json_string(s):
    s = s.strip()
    if s.startswith('{'):
        return parse_object(s)
    return None

def parse_object(s):
    s = s.strip()[1:]  # remove opening {
    result = {}
    while s:
        s = s.strip()
        if s.startswith('}'):
            break
        # Parse key
        if s.startswith('"'):
            key, s = parse_string(s)
        else:
            break
        s = s.strip()
        if s.startswith(':'):
            s = s[1:].strip()
        # Parse value
        val, s = parse_value(s)
        result[key] = val
        s = s.strip()
        if s.startswith(','):
            s = s[1:]
    return result

def parse_string(s):
    # s starts with "
    i = 1
    result = []
    while i < len(s):
        c = s[i]
        if c == '\\':
            i += 1
            esc = s[i]
            if esc == 'n': result.append('\n')
            elif esc == 't': result.append('\t')
            elif esc == 'r': result.append('\r')
            elif esc == '"': result.append('"')
            elif esc == '\\': result.append('\\')
            else: result.append(esc)
        elif c == '"':
            return ''.join(result), s[i+1:]
        else:
            result.append(c)
        i += 1
    return ''.join(result), ''

def parse_value(s):
    s = s.strip()
    if s.startswith('"'):
        return parse_string(s)
    elif s.startswith('{'):
        obj = parse_object(s)
        # find end of object to return remainder
        depth = 0
        i = 0
        in_str = False
        for i, c in enumerate(s):
            if c == '"' and (i == 0 or s[i-1] != '\\'):
                in_str = not in_str
            if not in_str:
                if c == '{': depth += 1
                elif c == '}':
                    depth -= 1
                    if depth == 0:
                        return obj, s[i+1:]
        return obj, ''
    elif s.startswith('true'):
        return True, s[4:]
    elif s.startswith('false'):
        return False, s[5:]
    elif s.startswith('null'):
        return None, s[4:]
    else:
        # number
        i = 0
        while i < len(s) and s[i] in '0123456789.-+eE':
            i += 1
        num_str = s[:i]
        try:
            if '.' in num_str:
                return float(num_str), s[i:]
            else:
                return int(num_str), s[i:]
        except:
            return None, s[i:]

try:
    payload_string = _item["json"]["output"]

    # Clean mailto links
    while "](mailto:" in payload_string:
        start = payload_string.rfind("[", 0, payload_string.index("](mailto:"))
        end = payload_string.index(")", payload_string.index("](mailto:")) + 1
        inner = payload_string[start+1 : payload_string.index("](mailto:")]
        payload_string = payload_string[:start] + inner + payload_string[end:]

    payload = parse_json_string(payload_string)

    _item["json"] = {
        "customer_id":               payload.get("customer_id"),
        "full_name":                 payload.get("full_name"),
        "service_type":              payload.get("service_type"),
        "customer_tenure":           payload.get("customer_tenure"),
        "overall_satisfaction":      payload.get("overall_satisfaction"),
        "nps_score":                 payload.get("nps_score"),
        "support_satisfaction":      payload.get("support_satisfaction"),
        "portal_rating":             payload.get("portal_rating"),
        "renewal_intent":            payload.get("renewal_intent"),
        "top_complaint":             payload.get("top_complaint"),
        "topic":                     payload.get("topic"),
        "sentiment":                 payload.get("sentiment"),
        "confidence":                payload.get("confidence"),
        "summary":                   payload.get("summary"),
        "churn_risk":                payload.get("churn_risk"),
        "retention_upsell_template": payload.get("retention_upsell_template"),
        "template_message":          payload.get("template_message"),
        "logged_at":                 payload.get("logged_at"),
    }

except Exception as e:
    _item["json"] = {
        "error":       str(e),
        "customer_id": _item["json"].get("customer_id", "UNKNOWN"),
        "logged_at":   _item["json"].get("logged_at", ""),
    }

return _item
